import pandas as pd, numpy as np
from itertools import combinations
from scipy.stats import norm
df = pd.read_csv('bn_sample_10k.csv')
cols = list(df.columns); n = len(df)

def partial_corr(x, y, cond):
    # regress x,y on cond, corr of residuals
    def resid(v, C):
        if len(C)==0: return df[v].values - df[v].mean()
        X = np.column_stack([np.ones(n)] + [df[c].values for c in C])
        b, *_ = np.linalg.lstsq(X, df[v].values, rcond=None)
        return df[v].values - X@b
    rx, ry = resid(x, cond), resid(y, cond)
    return np.corrcoef(rx, ry)[0,1]

def fisher_p(r, k):
    # k = size of cond set
    if abs(r)>=1: return 0.0
    z = 0.5*np.log((1+r)/(1-r))
    stat = abs(z)*np.sqrt(n-k-3)
    return 2*(1-norm.cdf(stat))

pairs = list(combinations(cols,2))
print("=== marginal corr ===")
for a,b in pairs:
    r = df[a].corr(df[b]); print(f"{a}-{b}: r={r:.4f} p={fisher_p(r,0):.2e}")
print("\n=== cond on each single ===")
for a,b in pairs:
    for c in cols:
        if c in (a,b): continue
        r = partial_corr(a,b,[c]); print(f"{a}-{b}|{c}: r={r:.4f} p={fisher_p(r,1):.2e}")
print("\n=== cond on pairs ===")
