import pandas as pd, numpy as np
df = pd.read_csv('bn_sample_10k.csv')
n = len(df)
# BIC for linear-Gaussian DAG: sum over nodes of n*log(RSS/n) + k*log(n)
def bic(parents):
    tot=0; k=0
    for t, ps in parents.items():
        y = df[t].values
        if not ps:
            rss = ((y-y.mean())**2).sum(); k+=2
        else:
            X = np.column_stack([np.ones(n)]+[df[p].values for p in ps])
            b,*_ = np.linalg.lstsq(X,y,rcond=None)
            rss = ((y-X@b)**2).sum(); k+=len(ps)+2
        tot += n*np.log(rss/n)
    return tot + k*np.log(n)
base = {'U':[],'Y':['U'],'R':['U'],'D':['U','Y'],'M':['U','R']}
print("base(U>Y,U>R,U>Y>D,U>R>M) BIC:", round(bic(base),1))
# alternatives: add Y-M edge
alt = {'U':[],'Y':['U'],'R':['U'],'D':['U','Y'],'M':['U','R','Y']}
print("+Y->M BIC:", round(bic(alt),1))
# drop U->D instead, add Y->M (still 6 edges)
alt2 = {'U':[],'Y':['U'],'R':['U'],'D':['Y'],'M':['U','R']}
