alt3 = {'U':[],'Y':['U'],'R':['U'],'D':['U','Y'],'M':['U']}
print("drop R->M BIC:", round(bic(alt3),1))
alt4 = {'U':[],'Y':['U'],'R':['U'],'D':['U'],'M':['U','R']}
print("drop Y->D BIC:", round(bic(alt4),1))
