import pandas as pd, numpy as np
df = pd.read_csv('bn_sample_10k.csv')
n = len(df); rng = np.random.default_rng(0)
parents = {'U':[],'Y':['U'],'R':['U'],'D':['U','Y'],'M':['U','R']}
cpd = {}
for t, ps in parents.items():
    y = df[t].values
    if not ps:
        cpd[t] = {'mu': y.mean(), 'sd': y.std(ddof=0)}
    else:
        X = np.column_stack([np.ones(n)]+[df[p].values for p in ps])
        b,*_ = np.linalg.lstsq(X, y, rcond=None)
        cpd[t] = {'b': b, 'ps': ps, 'sigma': (y - X@b).std(ddof=0)}
N = 10000
out = pd.DataFrame(index=range(N), columns=['U','Y','R','D','M'], dtype=float)
out['U'] = rng.normal(cpd['U']['mu'], cpd['U']['sd'], N)
out['Y'] = 0.0
def cond_sample(t, colvals):
    c = cpd[t]
    X = np.column_stack([np.ones(N)]+[colvals[p] for p in c['ps']])
    return X@c['b'] + rng.normal(0, c['sigma'], N)
out['R'] = cond_sample('R', {'U': out['U'].values})
out['D'] = cond_sample('D', {'U': out['U'].values, 'Y': out['Y'].values})
out['M'] = cond_sample('M', {'U': out['U'].values, 'R': out['R'].values})
out.to_csv('/app/final_bn_sample.csv', index=False)
print(out.describe().round(2))
print("Y unique:", out['Y'].unique(), "| NaNs:", out.isna().sum().sum(), "| rows:", len(out))
# sanity: intervened D mean should drop vs observational (Y parent 50->0, coef .45 => ~-22)
